// The Cartographer's atlas, navigable: every place ever planned (with its name and environment), the
// places only sketched, the regions of the atlas, you; in a game of many the players connected, each on their chunk,
// to follow (T42c). Drag or arrows to move, wheel or +/- to zoom. Nothing is generated by looking: what was never
// explored stays in the fog.

import type { Kernel } from '../kernel/kernel';
import type { Region } from '../kernel/atlas';
import { OPERATION_COLOR } from '../kernel/situation';
import { $, el } from './dom';

type View = Awaited<ReturnType<Kernel['atlasView']>>;

/** The players' colour, as on the situation table. */
const PLAYER = OPERATION_COLOR.giocatore;

const hue = (s: string) => {
  let h = 0;
  for (const ch of s) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return h % 360;
};

export class AtlasPanel {
  private root = $('#atlas');
  private canvas = el('canvas', { width: '760', height: '480' }) as HTMLCanvasElement;
  private info = el('div', { class: 'note' });
  private view?: View;
  private cx = 0;
  private cy = 0;
  private zoom = 14;
  private drag: { x: number; y: number; cx: number; cy: number } | null = null;
  onClose?: () => void;

  constructor(private k: Kernel) {
    k.bus.on('ui:atlas', () => void this.open());
    this.canvas.addEventListener('mousedown', (e) => (this.drag = { x: e.offsetX, y: e.offsetY, cx: this.cx, cy: this.cy }));
    window.addEventListener('mouseup', () => (this.drag = null));
    this.canvas.addEventListener('mousemove', (e) => {
      if (this.drag) {
        this.cx = this.drag.cx - (e.offsetX - this.drag.x) / this.zoom;
        this.cy = this.drag.cy - (e.offsetY - this.drag.y) / this.zoom;
        this.draw();
      } else this.hover(e.offsetX, e.offsetY);
    });
    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.zoom = Math.max(4, Math.min(40, this.zoom * (e.deltaY < 0 ? 1.15 : 0.87)));
      this.draw();
    });
    window.addEventListener(
      'keydown',
      (e) => {
        if (!this.isOpen) return;
        const step = 4 / Math.max(1, this.zoom / 10);
        const keys: Record<string, () => void> = {
          ArrowLeft: () => (this.cx -= step),
          ArrowRight: () => (this.cx += step),
          ArrowUp: () => (this.cy -= step),
          ArrowDown: () => (this.cy += step),
          '+': () => (this.zoom = Math.min(40, this.zoom * 1.2)),
          '-': () => (this.zoom = Math.max(4, this.zoom / 1.2)),
        };
        if (keys[e.key]) {
          keys[e.key]();
          this.draw();
        } else if (e.key === 'Escape' || e.code === 'KeyE') this.close();
        else return;
        e.preventDefault();
        e.stopPropagation();
      },
      true,
    );
  }

  get isOpen(): boolean {
    return !this.root.hidden;
  }

  async open(): Promise<void> {
    this.view = await this.k.atlasView();
    this.cx = this.view.here.cx + 0.5;
    this.cy = this.view.here.cy + 0.5;
    const close = el('button', { class: 'close' }, '×');
    close.onclick = () => this.close();
    const legend = el('div', { class: 'legend' }, el('span', { class: 'k planned' }, 'esplorato'), el('span', { class: 'k draft' }, 'abbozzato'), el('span', { class: 'k fog' }, 'mai visto'), el('span', { class: 'k region' }, 'regione'), el('span', { class: 'k you' }, 'tu'), ...(this.k.follow ? [el('span', { class: 'k player' }, 'giocatori')] : []));
    this.root.replaceChildren(el('div', { class: 'window' }, close, el('div', { class: 'title' }, "L'atlante del mondo"), legend, this.canvas, this.info, ...this.players(), el('div', { class: 'note' }, 'Trascina o frecce per spostarti, rotella o +/- per lo zoom. Guardare non genera nulla.')));
    this.root.hidden = false;
    this.onClose?.();
    this.draw();
  }

  close(): void {
    this.root.hidden = true;
    this.onClose?.();
  }

  /** The players connected (the master in a game of many, T42c): a button each, to centre the atlas on them or follow them. */
  private players(): HTMLElement[] {
    const list = this.view?.players ?? [];
    if (!this.k.follow) return [];
    if (!list.length) return [el('div', { class: 'note' }, 'Nessun giocatore collegato.')];
    return [
      el(
        'div',
        { class: 'row' },
        ...list.map((p) => {
          const b = el('button', {}, `Segui ${p.nome} (${p.cx},${p.cy})`);
          b.onclick = () => {
            this.close();
            this.k.follow?.(p.id);
          };
          return b;
        }),
      ),
    ];
  }

  private toScreen(cx: number, cy: number): [number, number] {
    return [(cx - this.cx) * this.zoom + this.canvas.width / 2, (cy - this.cy) * this.zoom + this.canvas.height / 2];
  }

  private draw(): void {
    const v = this.view;
    if (!v) return;
    const ctx = this.canvas.getContext('2d')!;
    const W = this.canvas.width;
    const H = this.canvas.height;
    const z = this.zoom;
    // Fog: what was never seen.
    ctx.fillStyle = '#06070c';
    ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = 'rgba(5, 217, 232, 0.06)';
    for (let x = Math.floor(this.cx - W / 2 / z); x < this.cx + W / 2 / z; x++) {
      const [sx] = this.toScreen(x, 0);
      ctx.beginPath();
      ctx.moveTo(sx, 0);
      ctx.lineTo(sx, H);
      ctx.stroke();
    }
    for (let y = Math.floor(this.cy - H / 2 / z); y < this.cy + H / 2 / z; y++) {
      const [, sy] = this.toScreen(0, y);
      ctx.beginPath();
      ctx.moveTo(0, sy);
      ctx.lineTo(W, sy);
      ctx.stroke();
    }
    // Regions: where the Cartographer placed environments (explored or not).
    for (const r of v.regions) this.drawRegion(ctx, r);
    for (const d of v.drafts) {
      const [sx, sy] = this.toScreen(d.cx, d.cy);
      ctx.fillStyle = 'rgba(120, 130, 150, 0.35)';
      ctx.fillRect(sx + 1, sy + 1, z - 2, z - 2);
    }
    for (const p of v.planned) {
      const [sx, sy] = this.toScreen(p.cx, p.cy);
      ctx.fillStyle = `hsl(${hue(p.layout)} 55% 42%)`;
      ctx.fillRect(sx + 1, sy + 1, z - 2, z - 2);
      if (z >= 26 && p.name) {
        ctx.fillStyle = '#e8f8f0';
        ctx.font = '9px monospace';
        ctx.fillText(p.name.slice(0, Math.floor(z / 6)), sx + 2, sy + z / 2);
      }
    }
    const [hx, hy] = this.toScreen(v.here.cx, v.here.cy);
    ctx.save();
    ctx.shadowColor = '#ff2a6d';
    ctx.shadowBlur = 12;
    ctx.strokeStyle = '#ff2a6d';
    ctx.lineWidth = 2;
    ctx.strokeRect(hx, hy, z, z);
    ctx.restore();
    const [ox, oy] = this.toScreen(0, 0);
    ctx.fillStyle = '#ffcf5c';
    ctx.fillRect(ox + z / 2 - 2, oy + z / 2 - 2, 4, 4);
    // The players connected: a violet dot where they stand, with their name.
    ctx.font = '11px sans-serif';
    for (const p of v.players) {
      const [px, py] = this.toScreen(p.x / this.k.config.chunkSize, p.y / this.k.config.chunkSize);
      ctx.fillStyle = PLAYER;
      ctx.beginPath();
      ctx.arc(px, py, Math.max(3, z / 6), 0, Math.PI * 2);
      ctx.fill();
      ctx.fillText(p.nome, px + 6, py - 6);
    }
  }

  private drawRegion(ctx: CanvasRenderingContext2D, r: Region): void {
    const [x0, y0] = this.toScreen(r.centro[0] - r.raggio, r.centro[1] - r.raggio);
    const size = (r.raggio * 2 + 1) * this.zoom;
    ctx.save();
    ctx.strokeStyle = `hsl(${hue(r.ambiente)} 80% 60%)`;
    ctx.shadowColor = ctx.strokeStyle;
    ctx.shadowBlur = 8;
    ctx.setLineDash([5, 4]);
    ctx.strokeRect(x0, y0, size, size);
    ctx.restore();
    ctx.fillStyle = `hsl(${hue(r.ambiente)} 80% 70%)`;
    ctx.font = '11px sans-serif';
    ctx.fillText(r.nome, x0 + 3, y0 - 4);
  }

  private hover(x: number, y: number): void {
    const v = this.view;
    if (!v) return;
    const cx = Math.floor((x - this.canvas.width / 2) / this.zoom + this.cx);
    const cy = Math.floor((y - this.canvas.height / 2) / this.zoom + this.cy);
    const p = v.planned.find((q) => q.cx === cx && q.cy === cy);
    const r = v.regions.find((q) => Math.max(Math.abs(q.centro[0] - cx), Math.abs(q.centro[1] - cy)) <= q.raggio);
    const d = v.drafts.some((q) => q.cx === cx && q.cy === cy);
    const who = v.players.filter((q) => q.cx === cx && q.cy === cy).map((q) => q.nome);
    this.info.textContent = `(${cx}, ${cy}) — ${p ? `«${p.name}» [${p.layout}]` : d ? 'abbozzato, non ancora progettato' : 'mai visto'}${r ? ` — regione «${r.nome}»` : ''}${who.length ? ` — qui: ${who.join(', ')}` : ''}`;
  }
}
